mapper.select:
select * from(
select row_number() over(partition by fp.finprod_market_id,f.eff_date order by f.eff_date desc) idx, fp.finprod_market_id as assetId ,fp.finprod_type2 as finprodType2, fp.profit_type as profitType, '01' changType, f.eff_date as changeDate, f.yield as assetRate,null as assetBonusReinvestRate,null as closePriceFull,null as costAmt, ifnull(f.UPDATE_TIME,f.CREATE_TIME) updatetime, null tradeId, null as status, null scino from fin_cash_calc_rule f left join fin_product fp on f.finprod_id=fp.finprod_id left join fin_cash_info cash on f.finprod_id=cash.finprod_id and f.cash_id=cash.cash_id left join fin_product_type fpt on fp.finprod_id=fpt.finprod_id where (fp.finprod_type2 in ('F01','F18','F07') or (fp.finprod_type2='F17' and fp.profit_type='02')) and (fpt.type_11!='013' or fpt.type_11 is null) and cash.cash_type_1='02' and f.yield is not null and ifnull(f.UPDATE_TIME,f.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
select row_number() over(partition by fp.finprod_market_id,f.val_date order by f.val_date desc) idx, fp.finprod_market_id as assetId ,fp.finprod_type2 as finprodType2, fp.profit_type as profitType, '02' changType, f.val_date as changeDate, f.valuation as assetRate,null as assetBonusReinvestRate,null as closePriceFull,null as costAmt, ifnull(f.UPDATE_TIME,f.CREATE_TIME) updatetime, null tradeId, null as status, null scino from fin_product_valuation f left join fin_product fp on f.finprod_id=fp.finprod_market_id and f.finprod_type2=fp.finprod_type2 where fp.finprod_type2 in ('F17','F06') and fp.profit_type in ('01','03') and f.valuation is not null and ifnull(f.UPDATE_TIME,f.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
select 1 idx, fp.finprod_market_id as assetId ,fp.finprod_type2 as finprodType2, fp.profit_type as profitType, '03' changType, f.trade_date as changeDate, null as assetRate,f.unit_cprice as assetBonusReinvestRate,null as closePriceFull,null as costAmt, ifnull(f.UPDATE_TIME,f.CREATE_TIME) updatetime, f.trade_id tradeId, case f.is_cancel when 'N' then 'E' when 'Y' then 'D' else end as status, null scino from trd_product_deal f left join fin_product fp on f.finprod_id=fp.finprod_id where fp.finprod_type2 in ('F17','F06') and fp.profit_type in ('01') and f.ps in ('T13') and f.trade_status='01' and f.unit_cprice is not null and ifnull(f.UPDATE_TIME,f.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
select row_number() over(partition by ftp.finprod_id,ftp.vdate order by ftp.vdate desc) idx, ftp.finprod_id as assetId ,ftp.finprod_type2 as finprodType2, null as profitType, '04' changType, ftp.vdate as changeDate, ftp.int_rate as assetRate,null as assetBonusReinvestRate,null as closePriceFull,null as costAmt, ifnull(ftp.UPDATE_TIME,ftp.CREATE_TIME) updatetime, null tradeId, null as status, null scino from fin_trade_product ftp where ftp.finprod_type2 in ('F02','F03','F04','F05','F15','F08','F09') and ftp.int_rate is not null and ifnull(ftp.UPDATE_TIME,ftp.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
select row_number() over(partition by fi.finprod_id,fi.eff_date order by fi.eff_date desc) idx, fi.finprod_id as assetId ,'XJ' as finprodType2, null as profitType, '05' changType, fi.eff_date as changeDate, fi.yield as assetRate,null as assetBonusReinvestRate,null as closePriceFull,null as costAmt, ifnull(fi.UPDATE_TIME,fi.CREATE_TIME) updatetime, null tradeId, null as status, sci.seq_no scino from fin_cash_calc_rule fi left join fin_cash_info cash on fi.cash_id=cash.cash_id left join STL_CAPACCT_INFO sci on sci.acct_no=fi.finprod_id where cash.cash_type_1='02' and cash.finprod_type='02' and fi.yield is not null and ifnull(fi.UPDATE_TIME,fi.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
select tt.* from ( select 1 idx, fi.acct_id as assetId ,'XJ' as finprodType2, null as profitType, '06' changType, fi.cdate as changeDate, null as assetRate,null as assetBonusReinvestRate,null as closePriceFull, sum(ifnull(fi.amount,0)) as costAmt, max(ifnull(fi.UPDATE_TIME,fi.CREATE_TIME)) updatetime, null tradeId, null as status, sci.seq_no scino from ptl_cash_position fi left join STL_CAPACCT_INFO sci on sci.acct_no=fi.acct_id left join fin_product fp on fi.portfolio_id=fp.finprod_market_id and fp.p_finprod_id is null and fp.finprod_type='F16' left join fin_product_add fpa on fp.finprod_id=fpa.finprod_id where fpa.profit_flag='03' group by fi.acct_id,fi.cdate,sci.seq_no)tt where tt.updatetime > #{updatetime,jdbcType=TIMESTAMP} and tt.costAmt!=0
union all
select row_number() over(partition by fi.sec_id,fi.value_date order by fi.value_date desc) idx, fi.sec_id as assetId ,fp.finprod_type2 as finprodType2, fpt.type_11 as profitType, '07' changType, fi.value_date as changeDate, null as assetRate,null as assetBonusReinvestRate,fi.close_price as closePriceFull,null as costAmt, ifnull(fi.UPDATE_TIME,fi.CREATE_TIME) updatetime, null tradeId, null as status, null scino from mst_bond_market_info fi left join fin_product fp on fi.sec_id=fp.finprod_market_id left join fin_product_type fpt on fp.finprod_id=fpt.finprod_id where fpt.type_11='013' and fi.close_price_full is not null and ifnull(fi.UPDATE_TIME,fi.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP} union all
select tt.* from ( select 1 idx, fp.finprod_market_id as assetId ,fp.finprod_type2 as finprodType2, fpt.type_11 as profitType, '08' changType, fi.cdate as changeDate, null as assetRate,null as assetBonusReinvestRate,null as closePriceFull, case when sum(ifnull(fi.share_amt,0))!=0 then sum(ifnull(fi.dsc_cost_amt,0))/sum(ifnull(fi.share_amt,0)) else 0 end as costAmt, max(ifnull(fi.UPDATE_TIME,fi.CREATE_TIME)) updatetime, null tradeId, null as status, fi.sec_acct_id scino from ptl_sec_valution fi left join fin_product fp on fi.finprod_id=fp.finprod_id left join fin_product_type fpt on fp.finprod_id=fpt.finprod_id where fpt.type_11='013' group by fp.finprod_market_id ,fp.finprod_type2,fpt.type_11,fi.cdate,fi.sec_acct_id)tt where tt.updatetime > #{updatetime,jdbcType=TIMESTAMP}
union all
select row_number() over(partition by fi.shares_id,fi.deal_date order by fi.deal_date desc) idx, fi.shares_id as assetId ,fp.finprod_type2 as finprodType2, null as profitType, '09' changType, fi.deal_date as changeDate, null as assetRate,null as assetBonusReinvestRate,fi.close_price as closePriceFull,null as costAmt, ifnull(fi.UPDATE_TIME,fi.CREATE_TIME) updatetime, null tradeId, null as status, null scino from mst_share_price fi left join fin_product fp on fi.shares_id=fp.finprod_market_id and fi.close_price is not null where ifnull(fi.UPDATE_TIME,fi.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
select tt.* from( select 1 idx, fp.finprod_market_id as assetId ,fp.finprod_type2 as finprodType2, null as profitType, '10' changType, fi.cdate as changeDate, null as assetRate,null as assetBonusReinvestRate,null as closePriceFull, case when sum(ifnull(fi.share_amt,0))!=0 then sum(ifnull(fi.dsc_cost_amt,0))/sum(ifnull(fi.share_amt,0)) else 0 end as costAmt, max(ifnull(fi.UPDATE_TIME,fi.CREATE_TIME)) updatetime, null tradeId, null as status, null scino from ptl_sec_valution fi left join fin_product fp on fi.finprod_id=fp.finprod_id where fp.finprod_type2='F10' group by fp.finprod_market_id ,fp.finprod_type2,fi.cdate)tt where tt.updatetime > #{updatetime,jdbcType=TIMESTAMP}
union all
select tt.* from ( select 1 idx, fp.finprod_market_id as assetId ,fp.finprod_type2 as finprodType2, fpt.type_11 as profitType, '11' changType, fi.cdate as changeDate, null as assetRate,null as assetBonusReinvestRate,null as closePriceFull, case when sum(ifnull(fi.share_amt,0))!=0 then sum(ifnull(fi.dsc_cost_amt,0))/sum(ifnull(fi.share_amt,0)) else 0 end as costAmt, max(ifnull(fi.UPDATE_TIME,fi.CREATE_TIME)) updatetime, null tradeId, null as status, null scino from ptl_sec_valution fi left join fin_product fp on fi.finprod_id=fp.finprod_id left join fin_product_type fpt on fp.finprod_id=fpt.finprod_id where fpt.type_11='013' group by fp.finprod_market_id ,fp.finprod_type2,fpt.type_11,fi.cdate)tt where tt.updatetime > #{updatetime,jdbcType=TIMESTAMP} ) a where 1=1 and a.idx=1

mapper.insert:
insert into CHB_ASSET_RATE(SEQNO, ASSET_ID,FINPROD_TYPE2,PROFIT_TYPE, CHANGE_TYPE, CHANGE_DATE, ASSET_RATE,ASSET_BONUSREINVEST_RATE,CLOSE_PRICE_FULL, COST_AMT,TRADE_ID, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,CCY,SCINO) select SEQNO, ASSET_ID,FINPROD_TYPE2,PROFIT_TYPE, CHANGE_TYPE, CHANGE_DATE, ASSET_RATE,ASSET_BONUSREINVEST_RATE,CLOSE_PRICE_FULL, COST_AMT,TRADE_ID, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,CCY,SCINO from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.finprodType2,jdbcType=VARCHAR} FINPROD_TYPE2, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.changType,jdbcType=VARCHAR} CHANGE_TYPE, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.assetRate,jdbcType=DECIMAL} ASSET_RATE, #{item.assetBonusReinvestRate,jdbcType=DECIMAL} ASSET_BONUSREINVEST_RATE, #{item.closePriceFull,jdbcType=DECIMAL} CLOSE_PRICE_FULL, #{item.costAmt,jdbcType=DECIMAL} COST_AMT, #{item.tradeId,jdbcType=VARCHAR} TRADE_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, sysdate UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, sysdate CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.ccy,jdbcType=VARCHAR} ccy, #{item.scino,jdbcType=VARCHAR} scino FROM DUAL
) TEMP where not exists (select 1 from CHB_ASSET_RATE CII where CII.ASSET_ID = TEMP.ASSET_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') and CII.CHANGE_TYPE = TEMP.CHANGE_TYPE and ((CII.TRADE_ID is not null and TEMP.TRADE_ID is not null and CII.TRADE_ID = TEMP.TRADE_ID) or (CII.TRADE_ID is null and TEMP.TRADE_ID is null)) and ((CII.SCINO is not null and TEMP.SCINO is not null and CII.SCINO = TEMP.SCINO) or (CII.SCINO is null and TEMP.SCINO is null))) ) de ;
UPDATE CHB_ASSET_RATE as A, ( select ASSET_RATE, ASSET_BONUSREINVEST_RATE, CLOSE_PRICE_FULL, COST_AMT, TRADE_ID, ORG_CODE, DEPT_CODE, REV_DATE, STATUS, REMARK, UPDATE_USER, UPDATE_TIME, CCY, SCINO from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.finprodType2,jdbcType=VARCHAR} FINPROD_TYPE2, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.changType,jdbcType=VARCHAR} CHANGE_TYPE, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.assetRate,jdbcType=DECIMAL} ASSET_RATE, #{item.assetBonusReinvestRate,jdbcType=DECIMAL} ASSET_BONUSREINVEST_RATE, #{item.closePriceFull,jdbcType=DECIMAL} CLOSE_PRICE_FULL, #{item.costAmt,jdbcType=DECIMAL} COST_AMT, #{item.tradeId,jdbcType=VARCHAR} TRADE_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, sysdate UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, sysdate CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.ccy,jdbcType=VARCHAR} ccy, #{item.scino,jdbcType=VARCHAR} scino FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_ASSET_RATE CII where CII.ASSET_ID = TEMP.ASSET_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') and CII.CHANGE_TYPE = TEMP.CHANGE_TYPE and ((CII.TRADE_ID is not null and TEMP.TRADE_ID is not null and CII.TRADE_ID = TEMP.TRADE_ID) or (CII.TRADE_ID is null and TEMP.TRADE_ID is null)) and ((CII.SCINO is not null and TEMP.SCINO is not null and CII.SCINO = TEMP.SCINO) or (CII.SCINO is null and TEMP.SCINO is null)))
